package com.astrocare.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final long expiration;
 public JwtService(@Value("${security.jwt.secret}") String secret,@Value("${security.jwt.expiration-seconds:3600}") long expiration){if(secret.length()<32)throw new IllegalArgumentException("security.jwt.secret must be at least 32 characters");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;}
 public String generate(UserDetails u){Map<String,Object> claims=Map.of("roles",u.getAuthorities().stream().map(a->a.getAuthority()).toList());return Jwts.builder().claims(claims).subject(u.getUsername()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration*1000)).signWith(key).compact();}
 public String username(String token){return parse(token).getPayload().getSubject();} public boolean valid(String t,UserDetails u){try{return username(t).equals(u.getUsername())&&!parse(t).getPayload().getExpiration().before(new Date());}catch(JwtException|IllegalArgumentException e){return false;}} public long expiration(){return expiration;} private Jws<Claims> parse(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t);}
}
